private static void validateP256Spki(byte[] publicKey) {
    try {
        java.security.PublicKey decoded = java.security.KeyFactory.getInstance("EC")
                .generatePublic(new java.security.spec.X509EncodedKeySpec(publicKey));
        if (!(decoded instanceof java.security.interfaces.ECPublicKey ec)
                || ec.getParams().getOrder().bitLength() != 256) {
            throw new IllegalArgumentException("invalid P-256 public key");
        }
    } catch (java.security.GeneralSecurityException failure) {
        throw new IllegalArgumentException("invalid P-256 public key", failure);
    }
}

